const path = require('path');
require('dotenv').config({ path: path.join(__dirname, '../../../../.env') });

const API_KEY = process.env.TRELLO_API_KEY;
const TOKEN = process.env.TRELLO_TOKEN;

if (!API_KEY || !TOKEN) {
    console.error("Error: TRELLO_API_KEY or TRELLO_TOKEN is missing from the .env file.");
    process.exit(1);
}

const boardId = process.argv[2];
if (!boardId) {
    console.error("Usage: node list_lists.js <boardId>");
    process.exit(1);
}

async function listLists() {
    const url = `https://api.trello.com/1/boards/${boardId}/lists?key=[secret]&token=[secret]&fields=name`;
    try {
        const response = await fetch(url);
        if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
        const lists = await response.json();
        console.log(`--- Lists in Board ${boardId} ---`);
        lists.forEach(l => console.log(`Name: "${l.name}"\nID: ${l.id}\n`));
    } catch (error) {
        console.error("Failed to fetch lists:", error.message);
    }
}

listLists();

# Méthode : Créer et utiliser une classe et ses objets en C++
**Objectif :** Modéliser une entité du monde réel en créant un nouveau type de données personnalisé, puis en instanciant des objets.
**Source :** C++ Tutorial for Beginners - Full Course — freeCodeCamp.org ([0:00](https://www.youtube.com/watch?v=vLnPwxZdW4Y&t=0s))

1. Définir la classe en utilisant le mot-clé class suivi du nom (ex: class Book { ... });
2. Ajouter le mot-clé public: suivi d'un deux-points pour rendre les attributs accessibles ;
3. Déclarer les attributs de la classe (ex: string title; string author; int pages;);
4. Créer un objet de cette classe dans la fonction main (ex: Book book1;);
5. Assigner des valeurs aux attributs de l'objet en utilisant la notation par point (ex: book1.title = "Harry Potter";);
6. Manipuler ou afficher les attributs de l'objet (ex: cout << book1.title;).

**Pièges signalés dans la vidéo :**
- Ne pas utiliser de logiciels de traitement de texte (Word, Google Docs) pour coder.
- Sur Windows, veillez à télécharger la version de Code::Blocks contenant 'minGW' pour obtenir automatiquement le compilateur.
- Confondre 'Build' (compilation du code en langage machine) et 'Run' (exécution du programme).
- Modifier manuellement des valeurs dupliquées (nom, âge) à plusieurs endroits dans un long code source au lieu d'utiliser des variables, ce qui devient fastidieux et source d'erreurs.
- Oublier de placer un point-virgule (;) à la fin d'une instruction en C++.

